22	/**
23	 * Hold the deployment-turn lock across a teardown whose liveness read and
24	 * process exit span multiple database transactions.
25	 */
26	export async function withDeploymentTurnLock<T>(
27	  deploymentName: string,
28	  action: () => Promise<T>
29	): Promise<T> {
30	  const reserved = await getLockDb().reserve();
31	  let acquired = false;
32	  try {
33	    await reserved`SELECT set_config('lock_timeout', '30s', false)`;
34	    await reserved`
35	      SELECT pg_advisory_lock(
36	        hashtext(${DEPLOYMENT_TURN_LOCK_NAMESPACE}),
37	        hashtext(${deploymentName})
38	      )
39	    `;
40	    acquired = true;
41	    return await action();
42	  } finally {
43	    try {
44	      if (acquired) {
45	        await reserved`
46	          SELECT pg_advisory_unlock(
47	            hashtext(${DEPLOYMENT_TURN_LOCK_NAMESPACE}),
48	            hashtext(${deploymentName})
49	          )
50	        `;
51	      }
52	    } finally {
53	      reserved.release();
54	    }
55	  }
56	}
