    WITH d AS (
      DELETE FROM runs
      WHERE status IN ('completed', 'cancelled', 'timeout')
        AND run_type IN ('chat_message', 'schedule', 'agent_run', 'internal', 'task')
        AND completed_at IS NOT NULL
        AND completed_at < now() - (${retentionDays}::int * interval '1 day')
      RETURNING id
    )
