/**
 * Whether a turn's obligation marker still exists (status pending), lapsed or
 * not. Distinct from {@link hasLiveTurnForMessage}: not a liveness probe but an
 * existence check. The marker is deleted only by the terminal election (reply
 * committed, terminal error emitted), so a claimed `thread_message` job with NO
 * marker is a turn that was already answered or terminalized — the dispatch
 * gate completes such jobs without delivering, because executing them would run
 * an agent whose reply the election is guaranteed to drop.
 */
export async function hasPendingTurnMarker(
  deploymentName: string,
  messageId: string
): Promise<boolean> {
  const sql = getDb();
  const rows = await sql<{ ok: number }>`
    SELECT 1 AS ok FROM public.runs
    WHERE status = 'pending'
      AND run_type = 'internal'
      AND queue_name = ${TURN_TIMEOUT_QUEUE}
      AND idempotency_key = ${turnMarkerKey(deploymentName, messageId)}
    LIMIT 1
  `;
  return rows.length > 0;
}

