27	/**
28	 * Routes jobs from queues to workers via SSE connections
29	 * Manages job acknowledgments and timeouts
30	 */
31	export class WorkerJobRouter {
32	  private pendingJobs: Map<string, PendingJob> = new Map(); // In-memory timeouts only
33	  /**
34	   * Claim-side recycle seam (the DeploymentManager in production). Optional:
35	   * unwired (tests, partial boots) means the gate is skipped and jobs deliver
36	   * exactly as before the gate existed.
37	   */
38	  private dispatchRecycler?: DispatchRecycler;
39	  private probeLiveTurn?: LiveTurnProbe;
40	  private terminalizeTurn?: TurnTerminalizer;
41	
42	  constructor(
43	    private queue: IMessageQueue,
44	    private connectionManager: WorkerConnectionManager,
45	    private loadPendingInputs: (
46	      deploymentName: string
47	    ) => Promise<PendingAgentRunInput[]> = listPendingAgentRunInputs,
48	  ) {}
49	
50	  /**
51	   * Wire the deployment manager into the dispatch-time staleness gate. Called
52	   * from the composition root alongside `setDeploymentActivityTracker` — the
53	   * router and the orchestrator are built separately.
54	   */
55	  setDispatchRecycler(
56	    recycler: DispatchRecycler,
57	    probeLiveTurn?: LiveTurnProbe,
58	    terminalizeTurn?: TurnTerminalizer
59	  ): void {
60	    this.dispatchRecycler = recycler;
61	    this.probeLiveTurn = probeLiveTurn;
62	    this.terminalizeTurn = terminalizeTurn;
63	  }
64	
65	  /**
66	   * Register a worker to receive jobs from its deployment queue
67	   * Each worker listens on its own queue: thread_message_{deploymentName}
68	   *
69	   * Note: This is idempotent - BullMQ's queue.work() handles duplicate registrations gracefully.
70	   * Safe to call multiple times (e.g., on worker reconnection or gateway restart).
71	   */
72	  async registerWorker(deploymentName: string): Promise<void> {
73	    const queueName = `thread_message_${deploymentName}`;
74	
75	    // Create queue if it doesn't exist
76	    await this.queue.createQueue(queueName);
77	
78	    // Register job handler (idempotent - BullMQ handles duplicates)
79	    // Start paused so jobs aren't consumed before the SSE connection is live.
80	    // The caller must call resumeWorker() after SSE connects.
81	    await this.queue.work(
82	      queueName,
83	      async (job: unknown) => {
84	        await this.handleJob(deploymentName, job);
85	      },
86	      { startPaused: true }
87	    );
88	
89	    const pendingInputs = await this.loadPendingInputs(deploymentName);
90	    for (const input of pendingInputs) {
91	      const payload = attachFreshRunJobToken(input);
92	      await this.queue.send(queueName, payload, {
93	        // Same deferral-aware budget as the consumer's thread-queue send: a
94	        // replayed input can also be claimed while the (reconnected) worker is
95	        // stale and mid-turn, and the dispatch gate defers it by throwing —
96	        // see sendToWorkerQueue in message-consumer.ts for the full rationale.
97	        retryLimit: 1800,
98	        retryDelay: 2,
99	        priority: 10,
100	      });
101	    }
102	    if (pendingInputs.length > 0) {
103	      logger.info(
104	        `Replayed ${pendingInputs.length} durable agent input(s) for ${deploymentName}`,
105	      );
106	    }
107	
108	    logger.info(`Registered worker for queue ${queueName}`);
109	  }
110	
111	  /**
112	   * Pause the BullMQ worker when SSE connection is lost
113	   * This prevents jobs from being processed when worker can't receive them
114	   */
115	  async pauseWorker(deploymentName: string): Promise<void> {
116	    const queueName = `thread_message_${deploymentName}`;
117	    await this.queue.pauseWorker(queueName);
118	    logger.info(
119	      `Paused job processing for ${deploymentName} - worker disconnected`
120	    );
121	  }
122	
123	  /**
124	   * Resume the BullMQ worker when SSE connection is established
125	   * Jobs will now be processed and sent to the worker
126	   */
127	  async resumeWorker(deploymentName: string): Promise<void> {
128	    const queueName = `thread_message_${deploymentName}`;
129	    await this.queue.resumeWorker(queueName);
130	    logger.info(
131	      `Resumed job processing for ${deploymentName} - worker connected`
132	    );
133	  }
134	
135	  /**
136	   * Handle a job from the queue and route it to the worker.
137	   *
138	   * Sends the job via SSE and waits for a delivery receipt from the worker.
139	   * If the worker doesn't acknowledge within the timeout, the job is retried
140	   * by BullMQ. This prevents jobs from being silently lost when sent to a
141	   * stale SSE connection (e.g., after a container dies without cleanly closing TCP).
142	   */
143	  private async handleJob(deploymentName: string, job: unknown): Promise<void> {
144	    // Extract job data and ID
145	    const jobData = (job as { data?: unknown }).data;
146	
147	    // Claim-side recycle gate: never deliver onto a worker whose connector
148	    // lease is dying or whose tooling no longer matches the org's connections.
149	    // Runs BEFORE the connection lookup — a recycle replaces the connection.
150	    // Deliberately un-caught: a throw here (deferral, recycle, or a genuine
151	    // failure) keeps the job undelivered and the queue retries it (fail
152	    // closed). Delivering on error would hand the turn to a sandbox holding a
153	    // dead or wrong credential, which is the defect this gate exists to stop.
154	    if (this.dispatchRecycler) {
155	      const decision = await gateDispatchOnStaleness({
156	        deploymentName,
157	        jobData,
158	        recycler: this.dispatchRecycler,
159	        probeLiveTurn: this.probeLiveTurn,
160	        terminalizeTurn: this.terminalizeTurn,
161	      });
162	      // "drop": the gate terminalized the turn (recycle rebuild failed) —
163	      // returning completes the held job so it cannot resurface as a zombie.
164	      if (decision === "drop") return;
165	    }
166	
167	    const connection = this.connectionManager.getConnection(deploymentName);
168	
169	    if (!connection) {
170	      logger.warn(
171	        `No connection for deployment ${deploymentName}, job will be retried`
172	      );
173	      throw new Error("Worker not connected");
174	    }
175	    const jobId =
176	      (job as { id?: string }).id ||
177	      `job-${Date.now()}-${Math.random().toString(36).substring(7)}`;
178	
179	    // Send job to worker via SSE with jobId wrapped in payload
180	    const jobPayload =
181	      typeof jobData === "object" && jobData !== null
182	        ? { payload: jobData, jobId: jobId }
183	        : { payload: { data: jobData }, jobId: jobId };
184	
185	    const sent = this.connectionManager.sendSSE(
186	      connection.writer,
187	      "job",
188	      jobPayload
189	    );
190	    if (!sent) {
191	      logger.warn(
192	        `SSE write failed for job ${jobId} to ${deploymentName}, will retry`
193	      );
194	      throw new Error("SSE write failed - worker connection may be dead");
195	    }
196	    this.connectionManager.touchConnection(deploymentName);
197	
198	    // Wait for delivery receipt from worker. If the SSE connection is stale
199	    // (container dead but TCP not yet closed), the worker will never ack and
200	    // BullMQ will retry the job after the timeout.
201	    await this.awaitDeliveryReceipt(jobId, deploymentName);
202	  }
203	
204	  /**
205	   * Wait for the worker to acknowledge receipt of a job.
206	   * Rejects after timeout so BullMQ retries the job.
207	   */
208	  private awaitDeliveryReceipt(
209	    jobId: string,
210	    deploymentName: string
211	  ): Promise<void> {
212	    return new Promise<void>((resolve, reject) => {
213	      const timeout = setTimeout(() => {
214	        this.pendingJobs.delete(jobId);
215	        logger.warn(
216	          `Job ${jobId} delivery receipt timeout - worker ${deploymentName} may be dead`
217	        );
218	        reject(
219	          new Error(
220	            `Delivery receipt timeout for job ${jobId} - worker may be dead`
221	          )
222	        );
223	      }, 5000); // 5 second timeout for delivery receipt
224	
225	      this.pendingJobs.set(jobId, {
226	        resolve: () => {
227	          clearTimeout(timeout);
228	          resolve();
229	        },
230	        reject: (err: Error) => {
231	          clearTimeout(timeout);
232	          reject(err);
233	        },
234	        timeout,
235	        jobId,
236	      });
237	    });
238	  }
239	
240	  /**
241	   * Acknowledge job completion from worker
242	   * Called when worker sends HTTP response
243	   */
244	  acknowledgeJob(jobId: string): void {
245	    const pendingJob = this.pendingJobs.get(jobId);
246	    if (pendingJob) {
247	      clearTimeout(pendingJob.timeout);
248	      pendingJob.resolve(undefined);
249	      this.pendingJobs.delete(jobId);
250	      logger.debug(`Job ${jobId} acknowledged`);
251	    } else {
252	      logger.warn(`Received acknowledgment for unknown job ${jobId}`);
253	    }
254	  }
255	
256	  /**
257	   * Get number of pending jobs
258	   */
259	  getPendingJobCount(): number {
260	    return this.pendingJobs.size;
261	  }
262	
263	  /**
264	   * Shutdown job router
265	   */
266	  shutdown(): void {
267	    // Reject all pending jobs
268	    for (const [jobId, pendingJob] of this.pendingJobs.entries()) {
269	      clearTimeout(pendingJob.timeout);
270	      pendingJob.reject(new Error("Job router shutting down"));
271	      logger.debug(`Rejected pending job ${jobId} due to shutdown`);
272	    }
273	    this.pendingJobs.clear();
274	  }
275	}
