  // the worker under the SAME name — the fresh worker will register its
  // queue consumer on THAT pod. Terminalizing here would surface a spurious
  // WORKER_STARTUP_FAILED to the user and race the winner's reply to
  // discharge the shared turn marker, which is exactly what this typed error
  // exists to prevent (see its doc in `@lobu/core`). Defer instead: the job
  // stays durable and undelivered, and the new owner's consumer delivers it.
  // Termination is bounded — the winner holds the lock only for its worker
  // subprocess lifetime, and if that worker dies the lock releases and the
  // retry re-runs this gate against a deployment whose pod-local tooling
  // state the teardown already cleared.
  if (error instanceof ConversationOwnedElsewhereError) {
    logger.info(
      { deploymentName },
      "Conversation claimed by another replica mid-recycle — deferring delivery to the new owner"
    );
    throw new StaleWorkerError(
      `Deployment ${deploymentName} was rebuilt by another replica — delivery retries under its new owner`,
      "ownership-handoff"
    );
  }
  logger.error(
    { deploymentName, error: getErrorMessage(error) },
    "Deployment recycle failed — terminalizing the held turn"
  );

test("REGRESSION: a cross-pod ownership handoff defers — it never terminalizes the turn", async () => {
  // The recycle's teardown releases this conversation's advisory lock, so
  // another replica can win it before our rebuild takes it back. That throws
  // the typed `ConversationOwnedElsewhereError`, which is a HANDOFF, not a
  // rebuild failure: the winner is bringing the worker up under the same
  // name and its pod will deliver this job. Terminalizing it here would show
  // the user a spurious "worker startup failed" and race the winner's reply
  // to discharge the shared turn marker.
  recycler.bornFingerprint = "fp-old";
  recycler.recycleError = new ConversationOwnedElsewhereError(
    "Conversation owned by another replica"
  );

  const err = (await queue
    .addJob(QUEUE, { id: "run-100", data: makePayload() })
    .catch((e: unknown) => e)) as StaleWorkerError;

  expect(err).toBeInstanceOf(StaleWorkerError);
  expect(err.reason).toBe("ownership-handoff");
  // Deferral contract: the retry must not consume the genuine-failure budget.
  expect((err as unknown as { deferral: boolean }).deferral).toBe(true);
  expect(deliveredJobs()).toHaveLength(0);
  expect(terminalized).toHaveLength(0);
});

