26	 * Run an async action over `items` in parallel batches of `batchSize`
27	 * (Promise.allSettled per batch — one failure never blocks the rest of the
28	 * batch). Rejections are reported through `onError`; the return value is the
29	 * number of fulfilled actions.
30	 */
31	export async function runInBatches<T>(
32	  items: readonly T[],
33	  batchSize: number,
34	  action: (item: T) => Promise<unknown>,
35	  onError: (item: T, reason: unknown) => void
36	): Promise<number> {
37	  let fulfilled = 0;
38	  for (let i = 0; i < items.length; i += batchSize) {
39	    const batch = items.slice(i, i + batchSize);
40	    const results = await Promise.allSettled(batch.map(action));
41	    for (let j = 0; j < results.length; j++) {
42	      const result = results[j];
43	      if (result?.status === "fulfilled") {
44	        fulfilled++;
45	      } else {
46	        onError(batch[j] as T, (result as PromiseRejectedResult).reason);
47	      }
48	    }
49	  }
50	  return fulfilled;
